&#x2F;&#x2F; Keep track of already hit notes
const hitNotesSet = new WeakSet();<p>&#x2F;&#x2F; Define hit zone (adjust based on your game layout)
const hitZoneY = window.innerHeight - 150; &#x2F;&#x2F; ~150px from bottom
const tolerance = 20; &#x2F;&#x2F; allowed error in pixels<p>function hitNotes() {
  document.querySelectorAll(&#x27;.note&#x27;).forEach(note =&gt; {
    if (hitNotesSet.has(note)) return; &#x2F;&#x2F; already triggered<p><pre><code>    const rect = note.getBoundingClientRect();
    const noteY = rect.top;

    &#x2F;&#x2F; Check if note is in hit zone
    if (Math.abs(noteY - hitZoneY) &lt;= tolerance) {
      let arrow = note.innerText.trim();

      let keyMap = {
        &#x27;↑&#x27;: &#x27;ArrowUp&#x27;,
        &#x27;↓&#x27;: &#x27;ArrowDown&#x27;,
        &#x27;←&#x27;: &#x27;ArrowLeft&#x27;,
        &#x27;→&#x27;: &#x27;ArrowRight&#x27;
      };

      let key = keyMap[arrow];
      if (key) {
        document.dispatchEvent(new KeyboardEvent(&#x27;keydown&#x27;, { key }));
        document.dispatchEvent(new KeyboardEvent(&#x27;keyup&#x27;, { key }));

        hitNotesSet.add(note); &#x2F;&#x2F; mark as hit
      }
    }
  });</code></pre>
}<p>setInterval(hitNotes, 20); &#x2F;&#x2F; check 50x per second
